package com.bank.vcs;

import java.util.ArrayList;
import java.util.List;

public class Branch {
    private final String name;
    private final List<Commit> commits = new ArrayList<>();
    private boolean shared;

    public Branch(String name, boolean shared) {
        this.name = name;
        this.shared = shared;
    }
    public String getName() { return name; }
    public boolean isShared() { return shared; }
    public List<Commit> getCommits() { return commits; }
    public void add(Commit c) { commits.add(c); }
    public boolean contains(String id) {
        return commits.stream().anyMatch(c -> c.getId().equals(id));
    }
    public Commit find(String id) {
        return commits.stream().filter(c -> c.getId().equals(id)).findFirst().orElse(null);
    }
}
