package com.bank.vcs;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// The three integration operations, each reshaping history differently.
public class GitOps {
    private static final Logger log = Logger.getLogger(GitOps.class.getName());
    private int seq;

    public GitOps(int startSeq) { this.seq = startSeq; }

    // MERGE: add a merge commit with both tips as parents. Preserves history. Safe on shared.
    public void merge(Branch from, Branch into) {
        int added = 0;
        for (Commit c : from.getCommits()) {
            if (!into.contains(c.getId())) { into.add(c); added++; }
        }
        Commit mc = new Commit("m" + (++seq),
            "Merge '" + from.getName() + "' into '" + into.getName() + "'", true);
        into.add(mc);
        final int a = added;
        log.info(() -> "MERGE: '" + from.getName() + "' -> '" + into.getName() + "' ("
                + a + " commit(s) + merge commit " + mc.getId() + ") — true history preserved");
    }

    // REBASE: replay 'feature' commits as NEW commits onto 'onto'. Rewrites history.
    // REFUSE if the branch being rebased is shared.
    public boolean rebase(Branch feature, Branch onto) {
        if (feature.isShared()) {
            log.severe(() -> "REFUSED: rebasing SHARED branch '" + feature.getName()
                    + "' would rewrite history others pulled. Rebase only PRIVATE branches.");
            return false;
        }
        List<Commit> replayed = new ArrayList<>();
        // start from onto's history, then re-create feature's unique commits as NEW commits
        List<Commit> newHistory = new ArrayList<>(onto.getCommits());
        for (Commit c : feature.getCommits()) {
            if (!onto.contains(c.getId())) {
                Commit replay = new Commit("r" + (++seq), c.getMessage() + " [rebased]", false);
                newHistory.add(replay);
                replayed.add(replay);
            }
        }
        feature.getCommits().clear();
        feature.getCommits().addAll(newHistory);
        log.info(() -> "REBASE: replayed " + replayed.size() + " commit(s) of '"
                + feature.getName() + "' onto '" + onto.getName()
                + "' — linear history, NEW commit ids");
        return true;
    }

    // CHERRY-PICK: copy ONE specific commit onto the current branch as a NEW commit.
    public void cherryPick(Commit source, Branch onto) {
        Commit copy = new Commit("p" + (++seq), source.getMessage() + " [cherry-picked]", false);
        onto.add(copy);
        log.info(() -> "CHERRY-PICK: copied " + source.getId() + " '" + source.getMessage()
                + "' onto '" + onto.getName() + "' as " + copy.getId()
                + " — just this commit, not its whole branch");
    }

    public void printHistory(Branch b) {
        log.info("history of '" + b.getName() + "':");
        for (Commit c : b.getCommits()) log.info("  " + c);
    }
}
