package com.bank.vcs;

import java.util.logging.*;

// Runnable demo: rebase a private feature, merge it to shared main, cherry-pick a hotfix.
public class MergeRebaseCherryDemo {
    private static final Logger log = Logger.getLogger(MergeRebaseCherryDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — merge vs rebase vs cherry-pick");

        GitOps git = new GitOps(0);

        // Shared main with two commits; main advanced while feature was being built.
        Branch main = new Branch("main", true);
        main.add(new Commit("c1", "transfer-service base", false));
        main.add(new Commit("c2", "add audit logging", false));

        // PRIVATE feature branch (branched earlier, now behind main).
        Branch feature = new Branch("feature/instant-transfer", false);
        feature.add(new Commit("c1", "transfer-service base", false));
        feature.add(new Commit("f1", "add instant transfer for SAV2001/CUR3001", false));

        // 1) REBASE the private feature onto latest main — clean linear history, safe.
        git.rebase(feature, main);
        git.printHistory(feature);

        // 2) MERGE the feature into shared main — preserves history, safe on shared.
        git.merge(feature, main);
        git.printHistory(main);

        // 3) A hotfix committed on a release branch must also go to main.
        Branch release = new Branch("release/1.3", true);
        release.add(new Commit("c1", "transfer-service base", false));
        Commit hotfix = new Commit("h1", "fix fee rounding (BigDecimal) for transfers", false);
        release.add(hotfix);

        // CHERRY-PICK just the hotfix onto main — not the rest of the release branch.
        git.cherryPick(hotfix, main);
        git.printHistory(main);
    }
}
